create or replace function public.schoolpro_consume_student_challenge(p_hash text) returns uuid language plpgsql set search_path='' as $$declare sid uuid;begin select student_id into sid from public.schoolpro_student_activation_challenges where token_hash=p_hash and expires_at>now() for update;if sid is null then return null;end if;perform 1 from public.schoolpro_students where id=sid and user_id is null and status in('active','graduated') for update;if not found then return null;end if;delete from public.schoolpro_student_activation_challenges where student_id=sid;return sid;end;$$;
